#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Timing;
using PVZEngine.Tools;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Contraptions
{
    [AutoBuffDefinition(VanillaBuffNames.Contraption.whirlwindAttack)]
    public class WhirlwindAttackBuff : BuffDefinition
    {
        public WhirlwindAttackBuff(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostAdd(Buff buff)
        {
            base.PostAdd(buff);
            var entity = buff.GetEntity();
            if (entity != null)
            {
                var level = buff.Level;
                var x = (level.GetGridLeftX() + level.GetGridRightX()) * 0.5f;
                var y = entity.Position.y;
                var z = (level.GetGridTopZ() + level.GetGridBottomZ()) * 0.5f;
                var position = new Vector3(x, y, z);
                var spawnParam = entity.GetSpawnParams();
                spawnParam.EntityParent = entity;
                entity.Spawn(VanillaEffectID.windSpeedline, position, spawnParam)?.Let(speedline =>
                {
                    speedline.Timeout = 1800;
                    SetWindSpeedline(buff, new EntityID(speedline));
                });
            }
        }
        public override void PostRemove(Buff buff)
        {
            base.PostRemove(buff);
            var speedlineID = GetWindSpeedline(buff);
            var speedline = speedlineID?.GetEntity(buff.Level);
            if (speedline != null && speedline.Exists())
            {
                speedline.Remove();
            }
            SetWindSpeedline(buff, null);
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var attackTimer = GetAttackTimer(buff);
            if (attackTimer == null)
            {
                attackTimer = TimerHelper.NewSecondTimer(ATTACK_INTERVAL);
                SetAttackTimer(buff, attackTimer);
            }
            if (attackTimer.RunToExpired())
            {
                attackTimer.Reset();
                var times = GetTimes(buff);
                if (times <= 0)
                {
                    buff.Remove();
                }
                else
                {
                    times--;
                    SetTimes(buff, times);
                    Attack(buff);
                    BlowMaplewheels(buff);
                }
            }
        }
        public static void Attack(Buff buff)
        {
            var entity = buff.GetEntity();
            if (!entity.ExistsAndAlive())
                return;
            var level = buff.Level;
            var effects = new DamageEffectList(VanillaDamageEffects.SLICE);
            var damage = GetDamage(buff);
            bool attacked = false;

            attackBuffer.Clear();
            attackDetector.DetectMultiple(entity, attackBuffer);
            foreach (var enemy in attackBuffer)
            {
                enemy.TakeDamage(damage, effects, entity);
                entity.Spawn(VanillaEffectID.cleaveAttack, enemy.GetBoundingBox().center);
                attacked = true;
            }
            if (attacked)
            {
                entity.PlaySound(VanillaSoundID.whirlwindAttack);
                entity.Level.ShakeScreen(3, 0, 5);
            }
        }
        public static void BlowMaplewheels(Buff buff)
        {
            foreach (var wheel in buff.Level.FindEntities(VanillaContraptionID.maplewheel))
            {
                Maplewheel.SetMaxSpinSpeed(wheel);
            }
        }
        public static int GetTimes(Buff buff) => buff.GetProperty<int>(PROP_TIMES);
        public static void SetTimes(Buff buff, int value) => buff.SetProperty(PROP_TIMES, value);
        public static float GetDamage(Buff buff) => buff.GetProperty<float>(PROP_DAMAGE);
        public static void SetDamage(Buff buff, float value) => buff.SetProperty(PROP_DAMAGE, value);
        public static EntityID? GetWindSpeedline(Buff buff) => buff.GetProperty<EntityID>(PROP_WIND_SPEEDLINE);
        public static void SetWindSpeedline(Buff buff, EntityID? value) => buff.SetProperty(PROP_WIND_SPEEDLINE, value);
        public static FrameTimer? GetAttackTimer(Buff buff) => buff.GetProperty<FrameTimer>(PROP_ATTACK_TIMER);
        public static void SetAttackTimer(Buff buff, FrameTimer? value) => buff.SetProperty(PROP_ATTACK_TIMER, value);

        public static readonly VanillaBuffPropertyMeta<int> PROP_TIMES = new VanillaBuffPropertyMeta<int>("times");
        public static readonly VanillaBuffPropertyMeta<float> PROP_DAMAGE = new VanillaBuffPropertyMeta<float>("damage");
        public static readonly VanillaBuffPropertyMeta<EntityID> PROP_WIND_SPEEDLINE = new VanillaBuffPropertyMeta<EntityID>("wind_speedline");
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_ATTACK_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("attack_timer");
        public const float ATTACK_INTERVAL = 1 / 5f;
        private static List<IEntityCollider> attackBuffer = new List<IEntityCollider>();
        private static Detector attackDetector = new LawnDetector()
        {
            canDetectInvisible = true
        };
    }
}
